package com.vibeguard.samples.employees; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*; import java.util.concurrent.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/employees") public class EmployeeController {private final Map<String,Profile> profiles=new ConcurrentHashMap<>(); public EmployeeController(){profiles.put("emp-1",new Profile("Ada","555-0100","Sam 555-0101","Engineering"));}@GetMapping("/{id}") public ResponseEntity<Profile> get(@PathVariable String id){return Optional.ofNullable(profiles.get(id)).map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}@PutMapping("/{id}") public ResponseEntity<Profile> update(@PathVariable String id,@Valid @RequestBody Profile profile){profiles.put(id,profile);return ResponseEntity.ok(profile);}record Profile(@NotBlank String name,@NotBlank String phone,@NotBlank String emergencyContact,@NotBlank String department){} }
